// ─── Component: re-center map on GPS ───────────────────────────────
function GPSControl({ onLocation }: { onLocation: (lat: number, lng: number) => void }) {
  const [locating, setLocating] = useState(false);
  const map = useMap();

  const handleGPS = useCallback(() => {
    if (!navigator.geolocation) {
      toast.error("Geolocation is not supported by your browser");
      return;
    }
    setLocating(true);
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const { latitude, longitude } = pos.coords;
        map.flyTo([latitude, longitude], 16, { duration: 1 });
        onLocation(latitude, longitude);
        toast.success("GPS location captured");
        setLocating(false);
      },
      (err) => {
        toast.error(`GPS failed: ${err.message}`);
        setLocating(false);
      },
      { enableHighAccuracy: true, timeout: 10_000 }
    );
  }, [map, onLocation]);

  return (
    <Button
      size="icon"
      variant="outline"
      onClick={handleGPS}
      disabled={locating}
      className="absolute right-12 bottom-2 z-[1000] h-9 w-9 bg-white shadow-md"
      title="Capture GPS location"
    >
      {locating ? (
        <Loader2 className="h-4 w-4 animate-spin" />
      ) : (
        <Crosshair className="h-4 w-4" />
      )}
    </Button>
  );
}

// ─── Component: click-on-map to capture coordinates ────────────────
function MapClickCapture({
  onMapClick,
}: {
  onMapClick: (lat: number, lng: number) => void;
}) {
  useMapEvents({
    click(e) {
      onMapClick(e.latlng.lat, e.latlng.lng);
    },
  });
  return null;
}

// ─── Component: FlyTo on demand ───────────────────────────────────
function FlyToMarker({
  lat,
  lng,
  zoom = 16,
}: {
  lat: number;
  lng: number;
  zoom?: number;
}) {
  const map = useMap();
  const hasFlown = useRef(false);

  useEffect(() => {
    if (!hasFlown.current && lat != null && lng != null) {
      map.flyTo([lat, lng], zoom, { duration: 1 });
      hasFlown.current = true;
    }
  }, [map, lat, lng, zoom]);

  return null;
}

// ─── Edit Dialog ──────────────────────────────────────────────────
function EditPlantationDialog({
  open,
  onOpenChange,
  record,
  onSave,
  onDelete,
  mode,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  record: Partial<PlantationRecord> | null;
  onSave: (data: PlantationRecord) => Promise<void>;
  onDelete?: (id: string) => Promise<void>;
  mode: "create" | "edit";
}) {
  const [name, setName] = useState("");
  const [category, setCategory] = useState<PlantationCategory>("OTHER");
  const [description, setDescription] = useState("");
  const [area, setArea] = useState("");
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (record) {
      setName(record.name || "");
      setCategory(record.category || "OTHER");
      setDescription(record.description || "");
      setArea(record.area != null ? String(record.area) : "");
    }
  }, [record]);

  const handleSave = async () => {
    if (!name.trim()) {
      toast.error("Name is required");
      return;
    }
    setSaving(true);
    try {
      await onSave({
        ...record,
        name: name.trim(),
        category,
        description: description.trim() || undefined,
        area: area ? parseFloat(area) : undefined,
        latitude: record?.latitude ?? 0,
        longitude: record?.longitude ?? 0,
      });
      onOpenChange(false);
      toast.success(mode === "create" ? "Plantation added" : "Plantation updated");
    } catch {
      toast.error("Failed to save");
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async () => {
    if (!record?.id || !onDelete) return;
    setSaving(true);
    try {
      await onDelete(record.id);
      onOpenChange(false);
      toast.success("Plantation deleted");
    } catch {
      toast.error("Failed to delete");
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>
            {mode === "create" ? "Add Plantation" : "Edit Plantation"}
          </DialogTitle>
          <DialogDescription>
            {mode === "create"
              ? "Click on the map or use GPS to set location, then fill in the details."
              : "Update the plantation details below."}
          </DialogDescription>
        </DialogHeader>

        <div className="grid gap-4 py-2">
          <div className="grid gap-2">
            <Label htmlFor="name">Name</Label>
            <Input
              id="name"
              placeholder="e.g. North Mango Grove"
              value={name}
              onChange={(e) => setName(e.target.value)}
            />
          </div>

          <div className="grid gap-2">
            <Label htmlFor="category">Category</Label>
            <Select
              value={category}
              onValueChange={(v) => setCategory(v as PlantationCategory)}
            >
              <SelectTrigger className="w-full">
                <SelectValue placeholder="Select category" />
              </SelectTrigger>
              <SelectContent>
                {PLANTATION_CATEGORIES.map((c) => (
                  <SelectItem key={c.value} value={c.value}>
                    <span className="flex items-center gap-2">
                      <span
                        className="inline-block h-3 w-3 rounded-full"
                        style={{ backgroundColor: c.color }}
                      />
                      {c.label}
                    </span>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="grid gap-2">
            <Label htmlFor="description">Description</Label>
            <Textarea
              id="description"
              placeholder="Optional notes..."
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              rows={3}
            />
          </div>

          <div className="grid gap-2">
            <Label htmlFor="area">Area (hectares)</Label>
            <Input
              id="area"
              type="number"
              step="0.01"
              placeholder="e.g. 2.5"
              value={area}
              onChange={(e) => setArea(e.target.value)}
            />
          </div>

          {record?.latitude != null && record?.longitude != null && (
            <div className="text-xs text-muted-foreground">
              <MapPin className="inline h-3 w-3 mr-1" />
              {record.latitude.toFixed(6)}, {record.longitude.toFixed(6)}
            </div>
          )}
        </div>

        <DialogFooter className="flex-row gap-2 sm:justify-end">
          {mode === "edit" && onDelete && (
            <Button
              variant="destructive"
              onClick={handleDelete}
              disabled={saving}
              className="mr-auto"
            >
              <Trash2 className="h-4 w-4 mr-1" />
              Delete
            </Button>
          )}
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={saving}>
            {saving && <Loader2 className="h-4 w-4 mr-1 animate-spin" />}
            {mode === "create" ? "Add" : "Save"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

// ─── Main MapTab ──────────────────────────────────────────────────
export default function MapTab() {
  const {
    items: plantations,
    queueDepth,
    isSyncing,
    add,
    update,
    remove,
    refresh,
    sync,
    error: queueError,
  } = useOfflineQueue({ autoSync: true, syncIntervalMs: 20_000 });

  const [searchQuery, setSearchQuery] = useState("");
  const [filterCategory, setFilterCategory] = useState<string>("ALL");
  const [editOpen, setEditOpen] = useState(false);
  const [editRecord, setEditRecord] = useState<Partial<PlantationRecord> | null>(null);
  const [editMode, setEditMode] = useState<"create" | "edit">("create");
  const [gpsCoord, setGpsCoord] = useState<[number, number] | null>(null);
  const [online, setOnline] = useState(typeof navigator !== 'undefined' ? navigator.onLine : true);
  const [activeTab, setActiveTab] = useState("map");

  // Online status
  useEffect(() => {
    const goOnline = () => setOnline(true);
    const goOffline = () => setOnline(false);
    window.addEventListener("online", goOnline);
    window.addEventListener("offline", goOffline);
    return () => {
      window.removeEventListener("online", goOnline);
      window.removeEventListener("offline", goOffline);
    };
  }, []);

  // Seed sample data if empty (first-run)
  useEffect(() => {
    let cancelled = false;
    async function seed() {
      const existing = await getAllPlantations();
      if (existing.length > 0 || cancelled) return;

      const samples: PlantationRecord[] = [
        {
          id: "demo-1",
          name: "North Mango Grove",
          category: "FRUIT_TREES",
          description: "Large mango plantation near the river",
          latitude: 23.8103,
          longitude: 90.4125,
          area: 12.5,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        },
        {
          id: "demo-2",
          name: "Timber Reserve East",
          category: "TIMBER",
          description: "Teak and sal timber plantation",
          latitude: 23.8150,
          longitude: 90.4200,
          area: 45.0,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        },
        {
          id: "demo-3",
          name: "Herbal Garden",
          category: "MEDICINAL",
          description: "Medicinal herb cultivation area",
          latitude: 23.8050,
          longitude: 90.4050,
          area: 3.2,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        },
        {
          id: "demo-4",
          name: "Rose Nursery",
          category: "FLOWER",
          description: "Commercial rose cultivation for local market",
          latitude: 23.8000,
          longitude: 90.4180,
          area: 1.8,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        },
        {
          id: "demo-5",
          name: "Rice Paddy South",
          category: "GRAIN",
          description: "Seasonal rice cultivation — Boro season",
          latitude: 23.7950,
          longitude: 90.4100,
          area: 30.0,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        },
      ];

      for (const s of samples) {
        await putPlantation(s);
        await enqueue({
          op: QUEUE_OP.CREATE,
          data: s,
          timestamp: new Date().toISOString(),
          synced: false,
        });
      }
      refresh();
    }
    seed();
    return () => {
      cancelled = true;
    };
  }, []);

  // Filter & search
  const filtered = useMemo(() => {
    let result = plantations;
    if (filterCategory !== "ALL") {
      result = result.filter((p) => p.category === filterCategory);
    }
    if (searchQuery.trim()) {
      const q = searchQuery.toLowerCase();
      result = result.filter(
        (p) =>
          p.name.toLowerCase().includes(q) ||
          (p.description ?? "").toLowerCase().includes(q) ||
          getCategoryLabel(p.category as PlantationCategory)
            .toLowerCase()
            .includes(q)
      );
    }
    return result;
  }, [plantations, filterCategory, searchQuery]);

  // Map click to create
  const handleMapClick = useCallback(
    (lat: number, lng: number) => {
      setEditRecord({ latitude: lat, longitude: lng });
      setEditMode("create");
      setEditOpen(true);
    },
    []
  );

  // Marker click to edit
  const handleMarkerClick = useCallback((record: PlantationRecord) => {
    setEditRecord(record);
    setEditMode("edit");
    setEditOpen(true);
  }, []);

  // Save handler
  const handleSave = async (data: PlantationRecord) => {
    if (editMode === "create") {
      await add(data);
    } else {
      await update(data);
    }
  };

  // Delete handler
  const handleDelete = async (id: string) => {
    await remove(id);
  };

  // GPS capture
  const handleGPSLocation = useCallback((lat: number, lng: number) => {
    setGpsCoord([lat, lng]);
  }, []);

  // Queue error toast
  useEffect(() => {
    if (queueError) {
      toast.error(queueError);
    }
  }, [queueError]);

  return (
    <div className="flex flex-col h-full gap-0">
      <Tabs value={activeTab} onValueChange={setActiveTab} className="flex flex-col h-full">
        <div className="flex items-center justify-between px-2 pt-1 pb-0">
          <TabsList>
            <TabsTrigger value="map">Map View</TabsTrigger>
            <TabsTrigger value="list">List View</TabsTrigger>
          </TabsList>

          <div className="flex items-center gap-1.5">
            {online ? (
              <Wifi className="h-3.5 w-3.5 text-emerald-600" />
            ) : (
              <WifiOff className="h-3.5 w-3.5 text-destructive" />
            )}
            {queueDepth > 0 && (
              <Badge variant="secondary" className="text-[10px] px-1.5 py-0">
                {queueDepth} queued
              </Badge>
            )}
            {isSyncing && <Loader2 className="h-3.5 w-3.5 animate-spin" />}
          </div>
        </div>

        {/* ─── Map Tab ────────────────────────────────────── */}
        <TabsContent value="map" className="flex-1 relative mt-0">
          {/* Search / Filter overlay */}
          <div className="absolute top-2 left-2 right-2 z-[1000] flex gap-2">
            <div className="relative flex-1">
              <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search plantations..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-9 h-9 bg-white/95 backdrop-blur shadow-md border-0"
              />
            </div>
            <Select value={filterCategory} onValueChange={setFilterCategory}>
              <SelectTrigger className="w-auto min-w-[140px] h-9 bg-white/95 backdrop-blur shadow-md border-0">
                <Layers className="h-4 w-4 mr-1" />
                <SelectValue placeholder="All categories" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="ALL">All Categories</SelectItem>
                {PLANTATION_CATEGORIES.map((c) => (
                  <SelectItem key={c.value} value={c.value}>
                    <span className="flex items-center gap-2">
                      <span
                        className="inline-block h-2.5 w-2.5 rounded-full"
                        style={{ backgroundColor: c.color }}
                      />
                      {c.label}
                    </span>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            <Button
              size="icon"
              variant="outline"
              className="h-9 w-9 bg-white/95 backdrop-blur shadow-md border-0"
              onClick={() => {
                setEditRecord({ latitude: 23.81, longitude: 90.41 });
                setEditMode("create");
                setEditOpen(true);
              }}
              title="Add new plantation"
            >
              <Plus className="h-4 w-4" />
            </Button>
          </div>

          {/* Leaflet Map */}
          <div className="h-full w-full">
            <MapContainer
              center={[23.8103, 90.4125]}
              zoom={13}
              className="h-full w-full z-0"
              zoomControl={false}
            >
              <TileLayer
                attribution='&copy; <a href="https://carto.com/">CARTO</a>'
                url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png"
              />

              <MapClickCapture onMapClick={handleMapClick} />
              <GPSControl onLocation={handleGPSLocation} />

              {gpsCoord && (
                <FlyToMarker lat={gpsCoord[0]} lng={gpsCoord[1]} />
              )}

              {filtered.map((p) => {
                const color = getCategoryColor(
                  p.category as PlantationCategory
                );
                return (
                  <CircleMarker
                    key={p.id}
                    center={[p.latitude, p.longitude]}
                    radius={10}
                    pathOptions={{
                      fillColor: color,
                      color: color,
                      weight: 2,
                      opacity: 0.9,
                      fillOpacity: 0.6,
                    }}
                    eventHandlers={{
                      click: () => handleMarkerClick(p),
                    }}
                  >
                    <Popup>
                      <div className="min-w-[160px]">
                        <h3 className="font-semibold text-sm">{p.name}</h3>
                        <div className="flex items-center gap-1 mt-1">
                          <span
                            className="inline-block h-2.5 w-2.5 rounded-full"
                            style={{ backgroundColor: color }}
                          />
                          <span className="text-xs text-muted-foreground">
                            {getCategoryLabel(p.category as PlantationCategory)}
                          </span>
                        </div>
                        {p.description && (
                          <p className="text-xs mt-1 text-muted-foreground">
                            {p.description}
                          </p>
                        )}
                        {p.area != null && (
                          <p className="text-xs mt-0.5 text-muted-foreground">
                            Area: {p.area} ha
                          </p>
                        )}
                        <p className="text-[10px] mt-1 text-muted-foreground">
                          {p.latitude.toFixed(5)}, {p.longitude.toFixed(5)}
                        </p>
                        <button
                          onClick={() => handleMarkerClick(p)}
                          className="mt-2 text-xs font-medium text-primary hover:underline flex items-center gap-1"
                        >
                          <Pencil className="h-3 w-3" />
                          Edit details
                        </button>
                      </div>
                    </Popup>
                  </CircleMarker>
                );
              })}
            </MapContainer>
          </div>
        </TabsContent>

        {/* ─── List Tab ───────────────────────────────────── */}
        <TabsContent value="list" className="flex-1 overflow-y-auto mt-0 px-2 pb-2">
          <div className="flex gap-2 mb-3">
            <div className="relative flex-1">
              <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-9 h-9"
              />
            </div>
            <Select value={filterCategory} onValueChange={setFilterCategory}>
              <SelectTrigger className="w-auto min-w-[140px] h-9">
                <Layers className="h-4 w-4 mr-1" />
                <SelectValue placeholder="All categories" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="ALL">All Categories</SelectItem>
                {PLANTATION_CATEGORIES.map((c) => (
                  <SelectItem key={c.value} value={c.value}>
                    <span className="flex items-center gap-2">
                      <span
                        className="inline-block h-2.5 w-2.5 rounded-full"
                        style={{ backgroundColor: c.color }}
                      />
                      {c.label}
                    </span>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {filtered.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-12 text-muted-foreground">
              <MapPin className="h-8 w-8 mb-2 opacity-50" />
              <p className="text-sm">No plantations found</p>
            </div>
          ) : (
            <div className="grid gap-2">
              {filtered.map((p) => {
                const color = getCategoryColor(
                  p.category as PlantationCategory
                );
                return (
                  <div
                    key={p.id}
                    className="flex items-center gap-3 p-3 rounded-lg border bg-card hover:bg-accent/50 cursor-pointer transition-colors"
                    onClick={() => handleMarkerClick(p)}
                  >
                    <span
                      className="h-3 w-3 rounded-full shrink-0"
                      style={{ backgroundColor: color }}
                    />
                    <div className="flex-1 min-w-0">
                      <h4 className="text-sm font-medium truncate">{p.name}</h4>
                      <p className="text-xs text-muted-foreground truncate">
                        {getCategoryLabel(p.category as PlantationCategory)}
                        {p.area != null ? ` · ${p.area} ha` : ""}
                      </p>
                    </div>
                    <Button
                      size="icon"
                      variant="ghost"
                      className="h-8 w-8 shrink-0"
                      onClick={(e) => {
                        e.stopPropagation();
                        handleMarkerClick(p);
                      }}
                    >
                      <Pencil className="h-3.5 w-3.5" />
                    </Button>
                  </div>
                );
              })}
            </div>
          )}
        </TabsContent>
      </Tabs>

      {/* Edit / Create Dialog */}
      <EditPlantationDialog
        open={editOpen}
        onOpenChange={setEditOpen}
        record={editRecord}
        onSave={handleSave}
        onDelete={editMode === "edit" ? handleDelete : undefined}
        mode={editMode}
      />
    </div>
  );
}
