import { openDB, type IDBPDatabase } from "idb";
import type { PlantationRecord, OfflineQueueItem } from "@/types/plantation";

const DB_NAME = "plantation-offline";
const DB_VERSION = 1;

const STORE_PLANTATIONS = "plantations";
const STORE_QUEUE = "queue";

let dbPromise: Promise<IDBPDatabase> | null = null;

function getDB(): Promise<IDBPDatabase> {
  if (!dbPromise) {
    dbPromise = openDB(DB_NAME, DB_VERSION, {
      upgrade(db) {
        if (!db.objectStoreNames.contains(STORE_PLANTATIONS)) {
          const ps = db.createObjectStore(STORE_PLANTATIONS, { keyPath: "id" });
          ps.createIndex("category", "category", { unique: false });
          ps.createIndex("name", "name", { unique: false });
        }
        if (!db.objectStoreNames.contains(STORE_QUEUE)) {
          const qs = db.createObjectStore(STORE_QUEUE, {
            keyPath: "id",
            autoIncrement: true,
          });
          qs.createIndex("synced", "synced", { unique: false });
        }
      },
    });
  }
  return dbPromise;
}

// ─── Plantation Store ─────────────────────────────────────────────

export async function getAllPlantations(): Promise<PlantationRecord[]> {
  const db = await getDB();
  return db.getAll(STORE_PLANTATIONS);
}

export async function getPlantation(id: string): Promise<PlantationRecord | undefined> {
  const db = await getDB();
  return db.get(STORE_PLANTATIONS, id);
}

export async function putPlantation(record: PlantationRecord): Promise<string> {
  const db = await getDB();
  if (!record.id) {
    record.id = crypto.randomUUID();
  }
  await db.put(STORE_PLANTATIONS, record);
  return record.id;
}

export async function deletePlantation(id: string): Promise<void> {
  const db = await getDB();
  await db.delete(STORE_PLANTATIONS, id);
}

export async function clearPlantations(): Promise<void> {
  const db = await getDB();
  await db.clear(STORE_PLANTATIONS);
}

// ─── Queue Store ─────────────────────────────────────────────────

export async function enqueue(item: Omit<OfflineQueueItem, "id">): Promise<number> {
  const db = await getDB();
  return db.add(STORE_QUEUE, item);
}

export async function getUnsyncedItems(): Promise<OfflineQueueItem[]> {
  const db = await getDB();
  const all = await db.getAllFromIndex(STORE_QUEUE, "synced", 0);
  return all as OfflineQueueItem[];
}

export async function markSynced(id: number): Promise<void> {
  const db = await getDB();
  const item = await db.get(STORE_QUEUE, id);
  if (item) {
    item.synced = true;
    await db.put(STORE_QUEUE, item);
  }
}

export async function clearSyncedItems(): Promise<void> {
  const db = await getDB();
  const tx = db.transaction(STORE_QUEUE, "readwrite");
  const index = tx.store.index("synced");
  let cursor = await index.openCursor(1);
  while (cursor) {
    await cursor.delete();
    cursor = await cursor.continue();
  }
  await tx.done;
}

export async function getQueueSize(): Promise<number> {
  const db = await getDB();
  return db.count(STORE_QUEUE);
}
